sys_script.script:
(function executeRule(current, previous) {
    var status = current.getValue('status');
    var prevStatus = previous ? previous.getValue('status') : '';
    if (status === prevStatus) return;

    var now = new GlideDateTime().getDisplayValue();

    // Manager approves -> moves to dept head
    if (status === 'pending_dh' && prevStatus === 'pending_mgr') {
        current.setValue('mgr_decision', 'approved');
        current.setValue('mgr_decision_date', now);
        current.setValue('manager', gs.getUserID());
    }

    // Dept head approves -> final approval
    if (status === 'approved' && prevStatus === 'pending_dh') {
        current.setValue('dh_decision', 'approved');
        current.setValue('dh_decision_date', now);
        current.setValue('dept_head', gs.getUserID());

        // If equipment needed, set equipment_status to pending_review
        if (current.getValue('equipment_needed') == '1') {
            current.setValue('equipment_status', 'pending_review');
        }
    }

    // Rejected from pending_mgr
    if (status === 'rejected' && prevStatus === 'pending_mgr') {
        current.setValue('mgr_decision', 'rejected');
        current.setValue('mgr_decision_date', now);
        current.setValue('manager', gs.getUserID());
    }

    // Rejected from pending_dh
    if (status === 'rejected' && prevStatus === 'pending_dh') {
        current.setValue('dh_decision', 'rejected');
        current.setValue('dh_decision_date', now);
        current.setValue('dept_head', gs.getUserID());
    }
})(current, previous);
